def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")


def _fresh_context(field_count: int = 12) -> Dict[str, Any]:
    return {
        "status": "fresh",
        "field_count": field_count,
        "fresh_field_count": field_count,
        "read_only": True,
        "live_write": False,
        "queries_console": False,
    }


def _base_analysis(**overrides: Any) -> SmartDSPAnalysisInput:
    payload = {
        "target_id": "ch:5",
        "source_role": "lead_vocal",
        "source_label": "Lead Vox",
        "mode": "soundcheck",
        "problem_hints": ("muddy",),
        "operator_intent": "offline smart DSP replay evaluation",
        "source_identity_confirmed": True,
        "source_identity_confidence": 0.88,
        "evidence_confidence": 0.84,
        "current_state_cache_freshness": _fresh_context(),
        "current_state_readback_available": True,
        "rollback_plan_available": True,
        "true_peak_headroom_db": 5.0,
        "feedback_risk": 0.12,
    }
    payload.update(overrides)
    return SmartDSPAnalysisInput(**payload)


@dataclass(frozen=True)
class SmartDSPReplayScenario:
    scenario_id: str
    description: str
    analysis: SmartDSPAnalysisInput
    expected_status: str
    expected_selected_strategy_id: str
    expected_method_family: str
    min_candidate_count: int = 1
    min_selected_total_score: float = 0.0
    required_global_blockers: Tuple[str, ...] = ()
    forbidden_global_blockers: Tuple[str, ...] = ()
    required_selected_parameter_keys: Tuple[str, ...] = ()
    expected_candidate_blockers: Dict[str, Tuple[str, ...]] = field(default_factory=dict)
    expected_candidate_parameter_keys: Dict[str, Tuple[str, ...]] = field(default_factory=dict)
    expected_alternative_tradeoff_reasons: Dict[str, Tuple[str, ...]] = field(
        default_factory=dict
    )

    def to_dict(self) -> Dict[str, Any]:
        payload = asdict(self)
        payload["analysis"] = asdict(self.analysis)
        payload["expected_candidate_blockers"] = {
            key: list(value) for key, value in self.expected_candidate_blockers.items()
        }
        payload["expected_candidate_parameter_keys"] = {
            key: list(value) for key, value in self.expected_candidate_parameter_keys.items()
        }
        payload["expected_alternative_tradeoff_reasons"] = {
            key: list(value)
            for key, value in self.expected_alternative_tradeoff_reasons.items()
        }
        return payload


