        "wing_osc_absolute_value_readback_parameter_values",
        "wing_osc_absolute_value_readback_parameter_count",
        "wing_osc_absolute_value_readback_parameter_reason_by_key",
        "wing_osc_absolute_value_readback_required_for_apply",
