        "wing_osc_readback_correction_exists_on_console_required",
        "wing_osc_readback_correction_exists_on_console_policy",
        "wing_osc_readback_native_osc_required_for_wing_applicable_candidate",
        "wing_osc_readback_path_must_match_firmware",
        "wing_osc_readback_target_id",
        "wing_osc_readback_target_surface_kind",
        "wing_osc_readback_target_index_surface",
        "wing_osc_readback_target_index",
